  let items = [...this.allItems]\n\n      // 分类筛选\n      if (this.catFilter !== 'all') {\n        items = items.filter(i => i.typeId === this.catFilter)\n      }\n\n      // 过期筛选\n      if (this.searchParams.expiryFilter === 'expired') {\n        items = items.filter(i => {\n          const d = getDaysLeft(i.expiryDate)\n          return d !== null && d < 0\n        })\n      } else if (this.searchParams.expiryFilter === '7days') {\n        items = items.filter(i => {\n          const d = getDaysLeft(i.expiryDate)\n          return d !== null && d >= 0 && d <= 7\n        })\n      } else if (this.searchParams.expiryFilter === '30days') {\n        items = items.filter(i => {\n          const d = getDaysLeft(i.expiryDate)\n          return d !== null && d >= 0 && d <= 30\n        })\n      }\n\n      // 关键词搜索（名称 + 分类 + 位置）\n      if (this.searchParams.keyword) {\n        const kw = this.searchParams.keyword.toLowerCase()\n        items = items.filter(i => {\n          const catName = (this.categories.find(c => c.id === i.typeId) || {}).name || ''\n          return (\n            i.name.toLowerCase().includes(kw) ||\n            catName.toLowerCase().includes(kw) ||\n            (i.location || '').toLowerCase().includes(kw) ||\n            (i.remark || '').toLowerCase().includes(kw)\n          )\n        })\n      }\n\n      // 排序\n      items.sort((a, b) => {\n        if (this.searchParams.sortBy === 'expiry') {\n          if (!a.expiryDate) return 1\n          if (!b.expiryDate) return -1\n          return new Date(a.expiryDate) - new Date(b.expiryDate)\n        } else if (this.searchParams.sortBy === 'name') {\n          return a.name.localeCompare(b.name, 'zh')\n        } else if (this.searchParams.sortBy === 'created') {\n          return new Date(b.createdAt) - new Date(a.createdAt)\n        } else if (this.searchParams.sortBy === 'price') {\n          return (a.price || 0) - (b.price || 0)\n        }\n        return 0\n      })\n\n      this.filteredItems = item