ta()\n        this.$message.success('修改成功')\n      }).catch(() => {})\n    }\n  }\n}\n</script>\n\n<style scoped>\n.item-list-page {\n  padding-bottom: 80px;\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.cat-tabs {\n  display: flex;\n  gap: 6px;\n  overflow-x: auto;\n  padding-bottom: 12px;\n  scrollbar-width: none;\n  -ms-overflow-style: none;\n}\n\n.cat-tabs::-webkit-scrollbar {\n  display: none;\n}\n\n.cat-tab {\n  flex-shrink: 0;\n  padding: 4px 12px;\n  border-radius: 14px;\n  font-size: 13px;\n  background-color: var(--bg-secondary);\n  color: var(--text-secondary);\n  cursor: pointer;\n  transition: all 0.2s;\n}\n\n.cat-tab.active {\n  background-color: var(--accent-light);\n  color: var(--accent);\n}\n\n.item-list {\n  padding-bottom: 20px;\n}\n</style>\n"],"sourceRoot":""}]);
