<template>
  <div class="page item-list-page">
    <!-- 页面头部 -->
    <div class="page-header flex-between">
      <span>📦 我的物品</span>
      <div class="header-actions">
        <el-button
          :type="batchMode ? 'primary' : 'text'"
          size="small"
          @click="toggleBatchMode"
        >
          {{ batchMode ? '取消多选' : '多选' }}
        </el-button>
        <el-button
          type="text"
          size="small"
          @click="$router.push('/statistics')"
        >
          📊
        </el-button>
      </div>
    </div>

    <!-- 搜索栏 -->
    <SearchBar
      v-if="!batchMode"
      :show-sort="true"
      @search="onSearch"
    />

    <!-- 分类横向筛选（单选模式时显示） -->
    <div v-if="!batchMode" class="cat-tabs">
      <span
        class="cat-tab"
        :class="{ active: catFilter === 'all' }"
        @click="catFilter = 'all'; filterItems()"
      >全部</span>
      <span
        v-for="cat in categories"
        :key="cat.id"
        class="cat-tab"
        :class="{ active: catFilter === cat.id }"
        @click="catFilter = cat.id; filterItems()"
      >
        {{ cat.name }}
      </span>
    </div>

    <!-- 物品列表 -->
    <div class="item-list" v-if="filteredItems.length > 0">
      <ItemCard
        v-for="item in filteredItems"
        :key="item.id"
        :item="item"
        :selectable="batchMode"
        :selected="selectedIds.includes(item.id)"
        @click="goEdit"
        @toggle-select="toggleSelect"
      />
    </div>

    <!-- 空状态 -->
    <div v-else class="empty-state">
      <div class="empty-icon">📭</div>
      <p>{{ batchMode ? '未选中任何物品' : '暂无物品，点击右下角按钮添加' }}</p>
    </div>

    <!-- 批量操作栏 -->
    <div v-if="batchMode" class="batch-bar">
      <span style="flex:1; font-size:13px; color: var(--text-secondary)">
        已选 {{ selectedIds.length }} 件
      </span>
      <el-button size="small" @click="selectedIds = []">清空</el-button>
      <el-button size="small" type="warning" @click="batchMove" :disabled="selectedIds.length === 0">
        移动分类
      </el-button>
      <el-button size="small" type="warning" @click="batchUpdateExpiry" :disabled="selectedIds.length === 0">
        修改过期
      </el-button>
      <el-button size="small" type="danger" @click="batchDelete" :disabled="selectedIds.length === 0">
        删除
      </el-button>
    </div>

    <!-- 浮动添加按钮（单选模式） -->
    <button
      v-if="!batchMode"
      class="fab"
      @click="$router.push('/add')"
    >
      +
    </button>
  </div>
</template>

<script>
import ItemCard from '@/components/ItemCard.vue'
import SearchBar from '@/components/SearchBar.vue'
import {
  loadItems,
  loadCategories,
  deleteItems,
  moveItems,
  updateItemsExpiry,
  getItemById
} from '@/store/index'
import { getDaysLeft } from '@/utils/format'

export default {
  name: 'ItemList',
  components: { ItemCard, SearchBar },
  data() {
    return {
      allItems: [],
      categories: [],
      filteredItems: [],
      catFilter: 'all',
      selectedIds: [],
      batchMode: false,
      // 搜索参数
      searchParams: {
        keyword: '',
        expiryFilter: 'all',
        sortBy: 'expiry'
      }
    }
  },
  created() {
    this.loadData()
  },
  methods: {
    loadData() {
      this.allItems = loadItems()
      this.categories = loadCategories()
      this.filterItems()
    },

    filterItems() {
      let items = [...this.allItems]

      // 分类筛选
      if (this.catFilter !== 'all') {
        items = items.filter(i => i.typeId === this.catFilter)
      }

      // 过期筛选
      if (this.searchParams.expiryFilter === 'expired') {
        items = items.filter(i => {
          const d = getDaysLeft(i.expiryDate)
          return d !== null && d < 0
        })
      } else if (this.searchParams.expiryFilter === '7days') {
        items = items.filter(i => {
          const d = getDaysLeft(i.expiryDate)
          return d !== null && d >= 0 && d <= 7
        })
      } else if (this.searchParams.expiryFilter === '30days') {
        items = items.filter(i => {
          const d = getDaysLeft(i.expiryDate)
          return d !== null && d >= 0 && d <= 30
        })
      }

      // 关键词搜索（名称 + 分类 + 位置）
      if (this.searchParams.keyword) {
        const kw = this.searchParams.keyword.toLowerCase()
        items = items.filter(i => {
          const catName = (this.categories.find(c => c.id === i.typeId) || {}).name || ''
          return (
            i.name.toLowerCase().includes(kw) ||
            catName.toLowerCase().includes(kw) ||
            (i.location || '').toLowerCase().includes(kw) ||
            (i.remark || '').toLowerCase().includes(kw)
          )
        })
      }

      // 排序
      items.sort((a, b) => {
        if (this.searchParams.sortBy === 'expiry') {
          if (!a.expiryDate) return 1
          if (!b.expiryDate) return -1
          return new Date(a.expiryDate) - new Date(b.expiryDate)
        } else if (this.searchParams.sortBy === 'name') {
          return a.name.localeCompare(b.name, 'zh')
        } else if (this.searchParams.sortBy === 'created') {
          return new Date(b.createdAt) - new Date(a.createdAt)
        } else if (this.searchParams.sortBy === 'price') {
          return (a.price || 0) - (b.price || 0)
        }
        return 0
      })

      this.filteredItems = items
    },

    onSearch(params) {
      this.searchParams = params
      this.filterItems()
    },

    goEdit(item) {
      if (this.batchMode) {
        this.toggleSelect(item.id)
      } else {
        this.$router.push(`/edit/${item.id}`)
      }
    },

    toggleBatchMode() {
      this.batchMode = !this.batchMode
      if (!this.batchMode) {
        this.selectedIds = []
      }
    },

    toggleSelect(id) {
      const idx = this.selectedIds.indexOf(id)
      if (idx >= 0) {
        this.selectedIds.splice(idx, 1)
      } else {
        this.selectedIds.push(id)
      }
    },

    async batchDelete() {
      try {
        await this.$confirm(`确定要删除选中的 ${this.selectedIds.length} 件物品吗？`, '批量删除', {
          confirmButtonText: '删除',
          cancelButtonText: '取消',
          type: 'warning'
        })
        deleteItems(this.selectedIds)
        this.selectedIds = []
        this.batchMode = false
        this.loadData()
        this.$message.success('删除成功')
      } catch (e) {
        // 用户取消
      }
    },

    batchMove() {
      this.$prompt('请输入目标分类ID', '批量移动分类', {
        inputValue: '',
        confirmButtonText: '确定',
        cancelButtonText: '取消'
      }).then(({ value }) => {
        if (!value) return
        moveItems(this.selectedIds, value)
        this.selectedIds = []
        this.batchMode = false
        this.loadData()
        this.$message.success('移动成功')
      }).catch(() => {})
    },

    batchUpdateExpiry() {
      this.$prompt('请输入新的过期日期 (YYYY-MM-DD)', '批量修改过期时间', {
        inputValue: '',
        confirmButtonText: '确定',
        cancelButtonText: '取消'
      }).then(({ value }) => {
        if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
          this.$message.warning('日期格式不正确，请使用 YYYY-MM-DD')
          return
        }
        updateItemsExpiry(this.selectedIds, value)
        this.selectedIds = []
        this.batchMode = false
        this.loadData()
        this.$message.success('修改成功')
      }).catch(() => {})
    }
  }
}
</script>

