/**
 * 日期和过期状态格式化工具
 */

/**
 * 格式化日期字符串
 * @param {string|Date} date - 日期
 * @param {string} fmt - 格式，默认 'YYYY-MM-DD'
 */
export function formatDate(date, fmt = 'YYYY-MM-DD') {
  if (!date) return ''
  const d = new Date(date)
  if (isNaN(d.getTime())) return ''
  const map = {
    'Y': d.getFullYear(),
    'M': String(d.getMonth() + 1).padStart(2, '0'),
    'D': String(d.getDate()).padStart(2, '0'),
    'h': String(d.getHours()).padStart(2, '0'),
    'm': String(d.getMinutes()).padStart(2, '0'),
    's': String(d.getSeconds()).padStart(2, '0')
  }
  return fmt.replace(/Y+|M+|D+|h+|m+|s+/g, key => map[key] || key)
}

/**
 * 获取距过期天数
 * @param {string} expiryDate - 过期日期 YYYY-MM-DD
 * @returns {number|null} 天数，null 表示无过期日期，负数表示已过期
 */
export function getDaysLeft(expiryDate) {
  if (!expiryDate) return null
  const exp = new Date(expiryDate)
  const now = new Date()
  now.setHours(0, 0, 0, 0)
  exp.setHours(0, 0, 0, 0)
  const diff = exp - now
  return Math.ceil(diff / (1000 * 60 * 60 * 24))
}

/**
 * 获取过期状态标签信息
 * @param {string} expiryDate - 过期日期
 * @returns {{ text: string, type: string, tagType: string }}
 */
export function getExpiryTag(expiryDate) {
  const days = getDaysLeft(expiryDate)
  if (days === null) return { text: '无过期', type: 'none', tagType: 'info' }
  if (days < 0) return { text: `已过期${Math.abs(days)}天`, type: 'expired', tagType: 'danger' }
  if (days === 0) return { text: '今天过期', type: 'today', tagType: 'danger' }
  if (days <= 7) return { text: `${days}天后过期`, type: 'warning', tagType: 'warning' }
  if (days <= 30) return { text: `${days}天后过期`, type: 'soon', tagType: 'primary' }
  return { text: `${days}天后过期`, type: 'normal', tagType: 'success' }
}

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes) {
  if (!bytes) return '0 B'
  const units = ['B', 'KB', 'MB', 'GB']
  let i = 0
  while (bytes >= 1024 && i < units.length - 1) {
    bytes /= 1024
    i++
  }
  return bytes.toFixed(1) + ' ' + units[i]
}

/**
 * 截断字符串
 */
export function truncate(str, maxLen = 20) {
  if (!str) return ''
  if (str.length <= maxLen) return str
  return str.slice(0, maxLen) + '...'
}

/**
 * 解析日期字符串，返回 Date 对象（处理 Safari 的 YYYY-MM-DD 格式）
 */
export function parseDate(str) {
  if (!str) return null
  const parts = str.split('-')
  if (parts.length !== 3) return null
  return new Date(parts[0], parts[1] - 1, parts[2])
}
