<template>
  <div
    class="item-card"
    :class="{ 'item-card--selected': selected }"
    @click="$emit('click', item)"
  >
    <!-- 复选框（批量模式时显示） -->
    <div v-if="selectable" class="item-card__checkbox" @click.stop>
      <el-checkbox
        :value="selected"
        @change="$emit('toggle-select', item.id)"
      />
    </div>

    <!-- 图片 -->
    <div class="item-card__photo">
      <img
        v-if="item.photos && item.photos.length > 0"
        :src="item.photos[0]"
        alt="物品图片"
      />
      <div v-else class="item-card__photo-placeholder">
        <span>📷</span>
      </div>
      <!-- 价格显示 -->
      <div v-if="item.price" class="item-card__price">¥{{ item.price }}</div>
      <!-- 过期状态角标 -->
      <div
        class="item-card__expiry-badge"
        :class="'expiry-' + expiryTag.type"
      >
        {{ expiryTag.text }}
      </div>
    </div>

    <!-- 信息 -->
    <div class="item-card__info">
      <div class="item-card__name">{{ item.name }}</div>
      <div class="item-card__meta">
        <span
          class="item-card__cat"
          :style="{ backgroundColor: categoryColor }"
        >
          {{ categoryName }}
        </span>
        <span v-if="item.location" class="item-card__location">
          📍 {{ item.location }}
        </span>
      </div>
      <div class="item-card__dates">
        <span>购买: {{ item.purchaseDate }}</span>
        <span v-if="item.expiryDate"> · 过期: {{ item.expiryDate }}</span>
      </div>
      <div v-if="item.remark" class="item-card__remark">{{ item.remark }}</div>
    </div>
  </div>
</template>

<script>
import { getCategoryById, getCategoryName, getCategoryColor } from '@/store/index'
import { getExpiryTag } from '@/utils/format'

export default {
  name: 'ItemCard',
  props: {
    item: {
      type: Object,
      required: true
    },
    selectable: {
      type: Boolean,
      default: false
    },
    selected: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    categoryName() {
      return getCategoryName(this.item.typeId)
    },
    categoryColor() {
      return getCategoryColor(this.item.typeId)
    },
    expiryTag() {
      return getExpiryTag(this.item.expiryDate)
    }
  }
}
</script>

