<template>
  <div class="search-bar">
    <!-- 搜索输入框 -->
    <el-input
      v-model="keyword"
      placeholder="搜索物品名称、分类、地点..."
      prefix-icon="el-icon-search"
      clearable
      @input="onKeywordChange"
    />

    <!-- 过期范围筛选 -->
    <div class="filter-chips">
      <span
        v-for="f in expiryFilters"
        :key="f.value"
        class="chip"
        :class="{ active: expiryFilter === f.value }"
        @click="setExpiryFilter(f.value)"
      >
        {{ f.label }}
      </span>
    </div>

    <!-- 排序选项 -->
    <div class="sort-row" v-if="showSort">
      <span class="sort-label">排序:</span>
      <span
        v-for="s in sortOptions"
        :key="s.value"
        class="chip"
        :class="{ active: sortBy === s.value }"
        @click="setSortBy(s.value)"
      >
        {{ s.label }}
      </span>
    </div>
  </div>
</template>

<script>
export default {
  name: 'SearchBar',
  props: {
    showSort: {
      type: Boolean,
      default: true
    }
  },
  data() {
    return {
      keyword: '',
      expiryFilter: 'all',
      sortBy: 'expiry',
      expiryFilters: [
        { label: '全部', value: 'all' },
        { label: '已过期', value: 'expired' },
        { label: '7天内', value: '7days' },
        { label: '30天内', value: '30days' }
      ],
      sortOptions: [
        { label: '按过期', value: 'expiry' },
        { label: '按名称', value: 'name' },
        { label: '按添加', value: 'created' },
        { label: '按价格', value: 'price' }
      ]
    }
  },
  methods: {
    onKeywordChange() {
      this.$emit('search', {
        keyword: this.keyword,
        expiryFilter: this.expiryFilter,
        sortBy: this.sortBy
      })
    },
    setExpiryFilter(val) {
      this.expiryFilter = val
      this.onKeywordChange()
    },
    setSortBy(val) {
      this.sortBy = val
      this.onKeywordChange()
    }
  }
}
</script>

